def font(size, bold=False):
    return ImageFont.truetype(BOLD if bold else REG, size)


def F(px, bold=False):
    """A font that is px tall in the final picture (the canvas is drawn SS times bigger)."""
    return font(int(px * SS), bold)


def lerp(a, b, t):
    return a + (b - a) * max(0.0, min(1.0, t))


def ease(t):
    t = max(0.0, min(1.0, t))
    return t * t * (3 - 2 * t)


# ------------------------------------------------------------------ the avatar (front view)
class Fig:
    def __init__(self, g, cx, floor, s):
        self.g, self.cx, self.floor, self.s = g, cx, floor, s

    def p(self, x, y):  # metres (x = her right is on the viewer's left) -> pixels
        return (self.cx - x * self.s, self.floor - y * self.s)

    def poly(self, pts, fill, outline=None):
        self.g.polygon([self.p(*q) for q in pts], fill=fill, outline=outline)

    def limb(self, a, b, wa, wb, fill):
        (x0, y0), (x1, y1) = a, b
        dx, dy = x1 - x0, y1 - y0
        n = math.hypot(dx, dy) or 1e-9
        nx, ny = -dy / n, dx / n
        self.poly([(x0 + nx * wa, y0 + ny * wa), (x1 + nx * wb, y1 + ny * wb),
                   (x1 - nx * wb, y1 - ny * wb), (x0 - nx * wa, y0 - ny * wa)], fill)
        for (x, y), w in ((a, wa), (b, wb)):
            cx, cy = self.p(x, y)
            r = w * self.s
            self.g.ellipse([cx - r, cy - r, cx + r, cy + r], fill=fill)

    def tracker(self, x, y, size=0.055, glow=False, label=None, side=1):
        cx, cy = self.p(x, y)
        r = size * self.s
        if glow:
            for k in (3, 2, 1):
                self.g.ellipse([cx - r * (1 + 0.5 * k), cy - r * (1 + 0.5 * k), cx + r * (1 + 0.5 * k), cy + r * (1 + 0.5 * k)],
                               outline=(255, 190, 90), width=3)
        self.g.rounded_rectangle([cx - r, cy - r * 0.8, cx + r, cy + r * 0.8], radius=r * 0.35, fill=TRK, outline=(120, 60, 10), width=3)
        self.g.ellipse([cx - r * 0.35, cy - r * 0.35, cx + r * 0.35, cy + r * 0.35], fill=(255, 225, 170))
        if label:
            f = F(26, True)
            tx = cx + side * (r * 2.4 + 90 * SS)
            self.g.line([cx + side * r * 1.2, cy, tx - side * 12, cy], fill=TRK, width=4)
            w = self.g.textlength(label, font=f)
            self.g.text((tx - (w if side < 0 else 0), cy - 18 * SS), label, fill=(255, 190, 90), font=f)

    def draw(self, arm=0.0, yaw=0.0, feet=0.06, hold=0.0, trk_glow=False, labels=False, swing=0.0, look=0.0, bend=0.0):
        g = self.g
        hip_y = 0.90
        ca, sa = math.cos(yaw), math.sin(yaw)
        # legs
        for sgn in (-1, 1):
            hip = (sgn * 0.085, hip_y)
            knee = (sgn * feet * 1.05, 0.48)
            ank = (sgn * feet, 0.085)
            self.limb(hip, knee, 0.058, 0.048, LIMB)
            self.limb(knee, ank, 0.048, 0.038, LIMB)
            self.poly([(sgn * feet - 0.05, 0.0), (sgn * feet + 0.05, 0.0), (sgn * feet + 0.045, 0.075), (sgn * feet - 0.045, 0.075)], (60, 70, 90))
        # pelvis: narrower and deeper while it turns
        wp = 0.155 * abs(ca) + 0.045 * abs(sa)
        self.poly([(-wp, 1.03), (wp, 1.03), (wp * 0.95, 0.84), (-wp * 0.95, 0.84)], BODY, (30, 90, 100))
        # belt line shows the turn
        bx = 0.155 * ca
        self.g.line([self.p(-wp, 0.98), self.p(wp, 0.98)], fill=(230, 245, 250), width=3 * SS)
        # torso: the chest follows the pelvis only a little
        yc = yaw * 0.25
        wc = 0.20 * abs(math.cos(yc)) + 0.05 * abs(math.sin(yc))
        self.poly([(-wc, 1.43), (wc, 1.43), (wp * 0.9, 1.03), (-wp * 0.9, 1.03)], BODY, (30, 90, 100))
        # arms: 0 = down along the body, 1 = straight out to the sides
        ang = math.radians(lerp(-83, 0, arm))
        for sgn in (-1, 1):
            sh = (sgn * (wc + 0.02), 1.38)
            a = ang - sgn * 0 + (swing * 0.35 * sgn if arm < 0.5 else 0)
            ux, uy = sgn * math.cos(a), math.sin(a)
            elbow = (sh[0] + ux * 0.29, sh[1] + uy * 0.29)
            hand = (elbow[0] + ux * 0.27, elbow[1] + uy * 0.27)
            self.limb(sh, elbow, 0.045, 0.04, LIMB)
            self.limb(elbow, hand, 0.04, 0.034, LIMB)
            cx, cy = self.p(*hand)
            r = 0.04 * self.s
            g.ellipse([cx - r, cy - r, cx + r, cy + r], fill=SKIN)
        # neck + head (always looks at us)
        self.poly([(-0.045, 1.45), (0.045, 1.45), (0.04, 1.53), (-0.04, 1.53)], SKIN)
        hx, hy = self.p(0, 1.63)
        r = 0.105 * self.s
        g.ellipse([hx - r, hy - r * 1.1, hx + r, hy + r * 1.1], fill=SKIN, outline=(150, 110, 80), width=3)
        for sgn in (-1, 1):
            ex = hx + sgn * r * 0.38 + look * r * 0.3
            g.ellipse([ex - 5 * SS, hy - r * 0.1 - 5 * SS, ex + 5 * SS, hy - r * 0.1 + 5 * SS], fill=(40, 40, 60))
        g.arc([hx - r * 0.35 + look * r * 0.3, hy + r * 0.1, hx + r * 0.35 + look * r * 0.3, hy + r * 0.55], 20, 160, fill=(120, 60, 60), width=3)
        # trackers: belt on her right side (viewer's left), feet on the insteps
        wx = 0.165 * ca
        self.tracker(wx, 0.96, size=0.05, glow=trk_glow, label="пояс" if labels else None, side=-1)
        for sgn, name in ((1, "ліва нога"), (-1, "права нога")):
            self.tracker(sgn * feet, 0.075, size=0.042, glow=trk_glow, label=name if labels else None, side=-sgn)
        if hold > 0:  # the hold ring around the figure's hand level
            cx, cy = self.p(0, 1.62)
            R = 0.26 * self.s
            g.arc([cx - R, cy - R, cx + R, cy + R], -90, -90 + 360 * hold, fill=GOOD, width=10 * SS)


def top_view(g, x0, y0, size, yaw, label=True):
    """The turn seen from above, so the idea of 'twist the hips' is clear."""
    g.rounded_rectangle([x0, y0, x0 + size, y0 + size], radius=18 * SS, fill=(34, 40, 54), outline=(70, 80, 100), width=3 * SS)
    cx, cy = x0 + size / 2, y0 + size / 2 + 8 * SS
    R = size * 0.27
    g.ellipse([cx - R * 1.2, cy - R * 0.85, cx + R * 1.2, cy + R * 0.85], outline=(130, 150, 170), width=3 * SS)
    fx, fy = math.sin(yaw), -math.cos(yaw)
    g.line([cx, cy, cx + fx * R * 1.2, cy + fy * R * 1.2], fill=GOOD, width=6 * SS)
    g.polygon([(cx + fx * R * 1.5, cy + fy * R * 1.5), (cx + fx * R * 1.1 - fy * 10 * SS, cy + fy * R * 1.1 + fx * 10 * SS),
               (cx + fx * R * 1.1 + fy * 10 * SS, cy + fy * R * 1.1 - fx * 10 * SS)], fill=GOOD)
    # tracker on the right side of the belt turns with the pelvis
    tx, ty = cx + math.cos(yaw) * R * 1.2, cy + math.sin(yaw) * R * 0.85
    g.rounded_rectangle([tx - 12 * SS, ty - 10 * SS, tx + 12 * SS, ty + 10 * SS], radius=5 * SS, fill=TRK)
    g.ellipse([cx - 6 * SS, cy - 6 * SS, cx + 6 * SS, cy + 6 * SS], fill=INK)
    if label:
        g.text((x0 + 16 * SS, y0 + 10 * SS), "вигляд зверху", fill=MUTED, font=F(22))
        g.text((x0 + 16 * SS, y0 + size - 34 * SS), "зелена стрілка — куди дивиться таз", fill=MUTED, font=F(18))


def watch_panel(g, x0, y0, highlight, t):
    """A copy of the panel next to the watch (the buttons she presses)."""
    rows = ["Наша калібровка", "Моделі трекерів"]
    k = SS
    w, h = 560 * k, (76 * len(rows) + 60) * k
    g.rounded_rectangle([x0, y0, x0 + w, y0 + h], radius=22 * k, fill=(34, 40, 54), outline=(70, 80, 100), width=3 * k)
    g.text((x0 + 24 * k, y0 + 14 * k), "Панель біля годинника", fill=MUTED, font=F(24))
    for i, text in enumerate(rows):
        yy = y0 + (56 + i * 76) * k
        on = text.startswith(highlight) if highlight else False
        g.rounded_rectangle([x0 + 24 * k, yy, x0 + w - 24 * k, yy + 62 * k], radius=14 * k, fill=(52, 60, 80), outline=(70, 80, 100), width=2 * k)
        if on:
            pulse = 0.5 + 0.5 * math.sin(t * 6)
            col = tuple(int(c * (0.65 + 0.35 * pulse)) for c in (255, 200, 80))
            g.rounded_rectangle([x0 + 18 * k, yy - 6 * k, x0 + w - 18 * k, yy + 68 * k], radius=18 * k, outline=col, width=6 * k)
        g.text((x0 + 44 * k, yy + 12 * k), text, fill=INK if on else (190, 198, 214), font=F(28, on))


# ------------------------------------------------------------------ one frame
def render(job):
    idx, t, dur = job
    sid, badge, title, _, _ = SCENES[idx]
    im = Image.new("RGB", (W * SS, H * SS), BG)
    g = ImageDraw.Draw(im)
    S = SS
    fig = Fig(g, 330 * S, 690 * S, 300 * S)
    u = t / dur  # 0..1 through the scene
    arm, yaw, feet, hold, glow, labels, swing = 0.0, 0.0, 0.07, 0.0, False, False, 0.0
    extra = None
    flash = 0.0
    big = None
    if sid == "prep":
        glow, labels, feet = True, True, 0.07
        swing = math.sin(t * 2) * 0.1
    elif sid == "tpose":
        feet = lerp(0.14, 0.05, ease(t / 2.0))
        arm = ease((t - 3.0) / 2.5)
        if t > 8.0:
            ph = ((t - 8.0) % 3.0) / 1.0
            hold = min(1.0, ph) if ph <= 1.0 else 1.0
            if ph > 1.0:
                flash = max(0.0, 1.0 - (ph - 1.0) * 4)
                big = ("клац!", GOOD) if ph < 1.7 else None
        extra = "tpose"
    elif sid == "hips":
        arm = 1.0 - ease(t / 1.5)
        if t > 4.0:
            k = t - 4.0
            amp = math.radians(32) * ease(k / 1.2)
            yaw = amp * math.sin(2 * math.pi * k / 2.6)
            left = max(0, 12 - k)
        else:
            left = None
        extra = ("hips", left)
    elif sid == "done":
        arm = 0.0
        extra = "done"
    elif sid in ("vrchat", "fix"):
        arm = 0.0
    fig.draw(arm=arm, yaw=yaw, feet=feet, hold=hold, trk_glow=glow, labels=labels, swing=swing)

    # side panels
    if sid == "hips":
        top_view(g, 760 * S, 120 * S, 440 * S, yaw)
    if sid == "vrchat":
        watch_panel(g, 680 * S, 150 * S, "Наша" if t < dur * 0.55 else "Моделі", t)
    if sid == "fix":
        g.text((700 * S, 170 * S), "Голос:", fill=MUTED, font=F(34))
        g.text((700 * S, 230 * S), "«Не бачу: ліва нога»", fill=WARN, font=F(46, True))
        g.text((700 * S, 330 * S), "Увімкни трекер і", fill=INK, font=F(34))
        g.text((700 * S, 380 * S), "відкалібруйся ще раз.", fill=INK, font=F(34))
    if sid == "tpose":
        lines = ["1. Калібрування", "2. Стань рівно", "3. Руки в сторони", "4. Натисни тригери"]
        for i, text in enumerate(lines):
            on = (t > 1.0 + i * 1.6)
            g.text((760 * S, (130 + i * 78) * S), text, fill=INK if on else (90, 100, 120), font=F(44, True))
            if on:
                ox, oy = 702 * S, (152 + i * 78) * S
                g.line([(ox, oy), (ox + 12 * S, oy + 14 * S), (ox + 36 * S, oy - 16 * S)], fill=GOOD, width=7 * S)
    if sid == "prep":
        g.ellipse([704 * S, 210 * S, 736 * S, 242 * S], fill=TRK)
        g.text((760 * S, 200 * S), "оранжеві — трекери", fill=TRK, font=F(34, True))
        g.text((760 * S, 270 * S), "Пояс — будь-де на ремені.", fill=INK, font=F(34))
        g.text((760 * S, 330 * S), "Ноги — зверху на ступнях.", fill=INK, font=F(34))
        g.text((760 * S, 410 * S), "Світлодіод має світитись", fill=MUTED, font=F(30))
        g.text((760 * S, 452 * S), "зеленим (трекер на зв'язку).", fill=MUTED, font=F(30))
    if sid == "intro":
        g.text((700 * S, 200 * S), "1 крок", fill=TRK, font=F(110, True))
        g.text((700 * S, 350 * S), "Калібруйся у VRChat —", fill=INK, font=F(44, True))
        g.text((700 * S, 410 * S), "решту програма робить сама", fill=INK, font=F(36))
    if extra == "done":
        ok = ease(t / 1.0)
        g.ellipse([760 * S, 130 * S, 940 * S, 310 * S], outline=GOOD, width=int(12 * S * ok) + 1)
        g.line([(795 * S, 225 * S), (835 * S, 265 * S), (915 * S, 170 * S)], fill=GOOD, width=int(18 * S * ok) + 1)
        g.text((760 * S, 350 * S), "Зріст: 164 см", fill=GOOD, font=F(46, True))
        g.text((760 * S, 420 * S), "Трекер на поясі:", fill=INK, font=F(32))
        g.text((760 * S, 466 * S), "спереду-справа", fill=INK, font=F(32, True))
    if isinstance(extra, tuple) and extra[0] == "hips":
        left = extra[1]
        if left is None:
            g.text((760 * S, 590 * S), "Опусти руки…", fill=WARN, font=F(46, True))
        else:
            g.text((760 * S, 590 * S), f"Крути!  ще {int(math.ceil(left))} с", fill=GOOD, font=F(54, True))
    if big:
        f = F(96, True)
        g.text((560 * S - g.textlength(big[0], font=f) / 2, 180 * S), big[0], fill=big[1], font=f)
    if flash > 0:
        ov = Image.new("RGB", im.size, (255, 255, 255))
        im = Image.blend(im, ov, flash * 0.7)
        g = ImageDraw.Draw(im)

    # title + step badge
    if badge:
        f = F(30, True)
        wb = g.textlength(badge, font=f)
        g.rounded_rectangle([40 * S, 28 * S, 40 * S + wb + 40 * S, 28 * S + 54 * S], radius=26 * S, fill=TRK)
        g.text((60 * S, 34 * S), badge, fill=(30, 20, 10), font=f)
    g.text((40 * S, (92 if badge else 44) * S), title, fill=INK, font=F(52, True))
    # progress dots
    for i in range(len(SCENES)):
        cx = (1240 - (len(SCENES) - i) * 26) * S
        g.ellipse([cx - 7 * S, 690 * S - 7 * S, cx + 7 * S, 690 * S + 7 * S], fill=TRK if i == idx else (70, 80, 100))
    return im.resize((W, H), Image.LANCZOS).tobytes()


# ------------------------------------------------------------------ voice + video
def run(cmd, **kw):
    return subprocess.run(cmd, check=True, **kw)


def duration(path):
    out = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(path)],
                         capture_output=True, text=True, check=True).stdout
    return float(out.strip())


def preview(out):
    """A few still frames to look at, without voice or video: make_tutorial.py --preview OUT_DIR"""
    out.mkdir(parents=True, exist_ok=True)
    times = {"intro": [2], "prep": [4], "tpose": [6, 10.2], "done": [3], "vrchat": [3, 8], "fix": [4]}
    for i, (sid, _, _, _, minimum) in enumerate(SCENES):
        for t in times[sid]:
            Image.frombytes("RGB", (W, H), render((i, t, 30.0))).save(out / f"{i}-{sid}-{t}.png")
    print("stills in", out)


def main():
    if sys.argv[1] == "--preview":
        return preview(Path(sys.argv[2]))
    out = Path(sys.argv[1])
    edge = sys.argv[2] if len(sys.argv) > 2 and not sys.argv[2].startswith("--") else "edge-tts"
    tmp = Path(tempfile.mkdtemp(prefix="fbtcal-tutorial-"))
    durs = []
    for i, (sid, _, _, text, minimum) in enumerate(SCENES):
        mp3 = tmp / f"{i}.mp3"
        run([edge, "--voice", "uk-UA-PolinaNeural", "--text", text, "--write-media", str(mp3)], stderr=subprocess.DEVNULL)
        durs.append(max(minimum, duration(mp3) + 1.2))
    # audio: each narration padded to its scene, then joined
    wavs = []
    for i, d in enumerate(durs):
        wav = tmp / f"{i}.wav"
        run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(tmp / f"{i}.mp3"), "-af", f"adelay=500|500,apad=pad_dur={d}", "-t", str(d),
             "-ar", "44100", "-ac", "1", str(wav)])
        wavs.append(wav)
    listing = tmp / "list.txt"
    listing.write_text("".join(f"file '{w}'\n" for w in wavs))
    audio = tmp / "audio.wav"
    run(["ffmpeg", "-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", str(listing), "-c", "copy", str(audio)])
    # frames -> ffmpeg through a pipe
    jobs = [(i, f / FPS, d) for i, d in enumerate(durs) for f in range(int(d * FPS))]
    print(f"{len(jobs)} frames, {sum(durs):.0f} s", flush=True)
    silent = tmp / "silent.mp4"
    ff = subprocess.Popen(["ffmpeg", "-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", "rgb24", "-s", f"{W}x{H}", "-r", str(FPS),
                           "-i", "-", "-c:v", "libx264", "-preset", "veryfast", "-crf", "22", "-pix_fmt", "yuv420p", str(silent)],
                          stdin=subprocess.PIPE)
    with Pool() as pool:
        for n, frame in enumerate(pool.imap(render, jobs, chunksize=8)):
            ff.stdin.write(frame)
            if n % 240 == 0:
                print(f"  {n}/{len(jobs)}", flush=True)
    ff.stdin.close()
    ff.wait()
    run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(silent), "-i", str(audio), "-c:v", "copy", "-c:a", "aac", "-b:a", "128k", "-shortest", str(out)])
    print("done", out, f"{out.stat().st_size / 1e6:.1f} MB")
    if "--frames" in sys.argv:  # a few still frames to look at
        starts = [0]
        for d in durs:
            starts.append(starts[-1] + d)
        for i, d in enumerate(durs):
            for frac in (0.5, 0.9):
                data = render((i, d * frac, d))
                Image.frombytes("RGB", (W, H), data).save(tmp / f"still-{i}-{int(frac * 10)}.png")
        print("stills in", tmp)


if __name__ == "__main__":
    main()
